using Godot;
using MySimulator.Rebuild;
using System;
using System.Collections.Generic;
namespace MySim {
// Actual force-driven bodies use the same race-control bridge as player and AI.
public partial class NativeHybridScenario : Node3D {
 sealed class Trial {public string Name;public NativeSuspensionVehicle Body;public Vehicle Vehicle;public float MaximumForce,Speed;public bool Settled;}
 readonly List<Trial> trials=new();float elapsed;bool launched,ended,fuelResolutionVerified;object fuelResolutionEvidence;
 public override void _Ready(){NativePhysicsClock.Configure();var whole=new Vehicle {fuel=45};var split120=new Vehicle {fuel=45};var split240=new Vehicle {fuel=45};NativeFuelUse.Consume(whole,0,10);for(int i=0;i<1200;i++)NativeFuelUse.Consume(split120,0,1f/120);for(int i=0;i<2400;i++)NativeFuelUse.Consume(split240,0,1f/240);float fine=split240.fuel;fuelResolutionVerified=whole.fuel<45&&Mathf.Abs(whole.fuel-split120.fuel)<.00001f&&Mathf.Abs(whole.fuel-fine)<.00001f;split240.fuel=20;NativeFuelUse.Consume(split240,1000000,1);var empty=new Vehicle {fuel=.000001f};NativeFuelUse.Consume(empty,100000000,1);fuelResolutionVerified&=split240.fuel<20&&split240.fuel>19&&empty.fuel==0;fuelResolutionEvidence=new {whole=whole.fuel,hz120=split120.fuel,hz240=fine,refilled=split240.fuel,depleted=empty.fuel};if(!fuelResolutionVerified)throw new Exception("Fuel depends on tick resolution or loses external refuel/clamp");var floor=new StaticBody3D {CollisionLayer=1,CollisionMask=4,Position=new Vector3(60,-.5f,500)};floor.AddChild(new CollisionShape3D {Shape=new BoxShape3D {Size=new Vector3(300,1,2000)}});AddChild(floor);
  foreach(string name in new[]{"off","automatic","manual","nonhybrid","brake-harvest","empty-fuel","stopped-empty-fuel"}){int car=name=="nonhybrid"?0:16;var body=new NativeSuspensionVehicle {CarIndex=car,Position=new Vector3(trials.Count*30,.8f,0)};AddChild(body);var vehicle=new Vehicle {carModel=car,human=true,externalPhysics=true,ersAuto=name=="automatic",ersOvertake=name=="manual"||name=="nonhybrid",ersCharge=name=="brake-harvest"?.5f:1,fuel=name.Contains("empty-fuel")?0:45};trials.Add(new Trial {Name=name,Body=body,Vehicle=vehicle});}
 }
 public override void _PhysicsProcess(double delta){if(ended)return;try{elapsed+=(float)delta;if(!launched&&elapsed>=3){foreach(var t in trials){t.Settled=t.Body.Contacts==4&&Mathf.Abs(t.Body.LinearVelocity.Y)<.15f;t.Body.SeedRollingVelocity(new Vector3(0,0,t.Name=="stopped-empty-fuel"?0:25));}launched=true;}
  if(!launched)return;foreach(var t in trials){var b=t.Body;var v=t.Vehicle;if(!b.GlobalPosition.IsFinite()||!b.LinearVelocity.IsFinite())throw new Exception("Nonfinite hybrid body");v.speed=b.LinearVelocity.Length();v.input=t.Name=="brake-harvest"?new DriverInput(0,1,0):new DriverInput(1,0,0);b.BindRaceControls(v,(float)delta);t.MaximumForce=Mathf.Max(t.MaximumForce,b.HybridDriveForce);t.Speed=v.speed;}
  if(elapsed<9)return;var baseline=trials[0];bool all=fuelResolutionVerified;var rows=new List<object>();foreach(var t in trials){bool boosted=t.Name=="automatic"||t.Name=="manual";bool ok=t.Settled&&(boosted?t.Speed>baseline.Speed+.05f&&t.MaximumForce>0&&t.Vehicle.ersCharge<.99f:t.Name=="stopped-empty-fuel"?t.Speed<.5f&&t.Vehicle.retired&&!t.Vehicle.finished:t.Name=="empty-fuel"?t.Speed<baseline.Speed-.05f&&t.Vehicle.fuel==0:t.Name=="brake-harvest"?t.Speed<.5f&&t.Vehicle.ersCharge>.5f:t.MaximumForce==0&&Mathf.Abs(t.Vehicle.ersCharge-1)<.00001f);ok&=float.IsFinite(t.Vehicle.fuel)&&t.Vehicle.fuel>=0&&(t.Name.Contains("empty-fuel")||t.Vehicle.fuel<45);all&=ok;rows.Add(new {trial=t.Name,ok,t.Settled,speed=t.Speed,baselineSpeed=baseline.Speed,maximumHybridForce=t.MaximumForce,charge=t.Vehicle.ersCharge,fuel=t.Vehicle.fuel,retired=t.Vehicle.retired,retirementReason=t.Vehicle.retirementReason,contacts=t.Body.Contacts});}
  string path=System.Environment.GetEnvironmentVariable("MYSIM_NATIVE_HYBRID_CHECKS");System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path));System.IO.File.WriteAllText(path,System.Text.Json.JsonSerializer.Serialize(new {all,fuelResolutionVerified,fuelResolutionEvidence,physicsHz=Engine.PhysicsTicksPerSecond,rows,scope="Actual native force boost/manual/automatic/battery-state integration; provisional combustion work/empty-fuel model; simplified existing harvest, not hybrid energy-conservation or real-world calibration acceptance"},new System.Text.Json.JsonSerializerOptions {WriteIndented=true}));ended=true;GD.Print(all?"PASS native ERS acceleration and battery-state bridge":"FAIL native ERS acceleration or battery-state bridge");CleanExit.Request(this,all?0:1);
 }catch(Exception e){ended=true;GD.PushError(e.ToString());CleanExit.Request(this,1);}}
}
}
